ystem-mcq-part-2">Operating System MCQ Part 2</a></li><li class="leftmenu"><a href="/computer-graphics-mcq">Computer Graphics MCQ</a></li><li class="leftmenu"><a href="/css-mcq">CSS MCQ</a></li><li class="leftmenu"><a href="/python-mcq">Python MCQ</a></li><li class="leftmenu"><a href="/python-mcq-part-2">Python MCQ Part 2</a></li><li class="leftmenu"><a href="/cpp-mcq">C++ MCQ</a></li><li class="leftmenu"><a href="/cpp-mcq-part-2">C++ MCQ Part 2</a></li><li class="leftmenu"><a href="/digital-electronics-mcq">Digital Electronics MCQ</a></li><li class="leftmenu"><a href="/oops-mcq">OOPS MCQ</a></li><li class="leftmenu"><a href="/javascript-mcq">JavaScript MCQ</a></li><li class="leftmenu"><a href="/c-language-mcq">C language MCQ</a></li><li class="leftmenu"><a href="/c-language-mcq-part-2">C language MCQ Part-2</a></li><li class="leftmenu"><a href="/dbms-mcq">DBMS MCQ</a></li><li class="leftmenu"><a href="/software-engineering-mcq">Software Engineering MCQ</a></li><li class="leftmenu"><a href="/computer-fundamental-mcq">Computer Fundamental MCQ</a></li><li class="leftmenu"><a href="/computer-fundamental-mcq-part-2">Computer Fundamental MCQ Part 2</a></li><li class="leftmenu"><a href="/sql-mcq">SQL MCQ</a></li><li class="leftmenu"><a href="/data-mining-mcq">Data Mining MCQ</a></li><li class="leftmenu"><a href="/artificial-intelligence-mcq">Artificial Intelligence MCQ</a></li><li class="leftmenu"><a href="/data-structure-mcq">Data Structure MCQ</a></li><li class="leftmenu"><a href="/discrete-mathematics-mcq">Discrete Mathematics MCQ</a></li><li class="leftmenu"><a href="/html-mcq">HTML MCQ</a></li><li class="leftmenu"><a href="/python-mcq">Python MCQ</a></li><li class="leftmenu"><a href="/java-mcq">Java MCQ</a></li><li class="leftmenu"><a href="/thread-priority-mcqs-in-java">Thread Priority MCQs in Java</a></li><li class="leftmenu"><a href="/english-grammar-mcq-for-competitive-exam">English Grammar MCQ For Competitive Exam</a></li><li class="leftmenu"><a href="/java-multithreading-mcqs">Java Multithreading MCQs</a></li></ul></div></div></div></div></div></div><div class="col-12 col-md-7"><div class="overview"><html><head></head><body><div id="city"><table><tbody><tr><td><div id="bottomnextup"><a class="next" href="python-programs">next →</a> <a class="next" href="python-website-blocker-script-deployment-on-windows">← prev</a></div><h1 class="h1">Python MCQ Part - 2</h1><div style="font-size:14px;margin-top:5px;margin-bottom:5px;color:#6f6e6e"><span>16 Apr 2025</span> | <span><i aria-hidden="true" class="fa fa-clock-o"></i> 13 min read</span></div><p class="pq">1) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print(print(print("javatpoint")))  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>javatpoint None None</li><li>None None javatpoint</li><li>None javatpoint None</li><li>Javatpoint</li></ol><button class="showanswer" onclick="showhide(1)"><span id="btntext1">Show Answer</span></button> <button class="workspace" onclick="showworkspace(1)"><span id="btntext1">Workspace</span></button><div id="workspace1"></div><div class="testanswer" id="answer1"><p><strong>Answer:</strong> (a) javatpoint None None</p><p><strong>Explanation:</strong> In this program, the inner print function will run first as compared to the outer print function. Therefore, the correct output of this program is "javatpoint None None".</p></div><hr/><p class="pq">2) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print(True ** False / True)  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>True ** False / True</li><li>1.0</li><li>1 ** 0 / 1</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(2)"><span id="btntext2">Show Answer</span></button> <button class="workspace" onclick="showworkspace(2)"><span id="btntext2">Workspace</span></button><div id="workspace2"></div><div class="testanswer" id="answer2"><p><strong>Answer:</strong> (b) 1.0</p><p><strong>Explanation:</strong> Binary values</p><p>True = 1</p><p>False = 0</p><p>(1 ** 0 / 1) = (1<sup>0</sup>/ 1) = 1.0</p><p>Therefore, option (b) is the correct output of this program.</p></div><hr/><p class="pq">3) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">int1 = 10
int2 = 6
if int != int2:
    int2 = ++int2
    print(int1 - int2)  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>2</li><li>4</li><li>6</li><li>None</li></ol><button class="showanswer" onclick="showhide(3)"><span id="btntext3">Show Answer</span></button> <button class="workspace" onclick="showworkspace(3)"><span id="btntext3">Workspace</span></button><div id="workspace3"></div><div class="testanswer" id="answer3"><p><strong>Answer:</strong> (b) 4</p><p><strong>Explanation:</strong> In the Python Programming Language, Increment and Decrement condition is not valid.</p><p>(y = ++y) = (y = y)</p><p>So, the output of this program is 4.</p></div><hr/><p class="pq">4) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">int1 = 10
int2 = 6
if int != int2:
    int2 = ++int1
    print(int1 - int2)  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>2</li><li>4</li><li>0</li><li>No Output</li></ol><button class="showanswer" onclick="showhide(4)"><span id="btntext4">Show Answer</span></button> <button class="workspace" onclick="showworkspace(4)"><span id="btntext4">Workspace</span></button><div id="workspace4"></div><div class="testanswer" id="answer4"><p><strong>Answer:</strong> (c) 0</p><p><strong>Explanation:</strong> In the Python Programming Language, Increment and Decrement condition is not valid.</p><p>int1 = (10)</p><p>int2 = (6)</p><p>int2 = ++int1</p><p>int2 = 10</p><p>print(10 - 10)</p><p>So, the output of this program is the 0.</p></div><hr/><p class="pq">5) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print(6 + 5 - 4 * 3 / 2 % 1)  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>7</li><li>7.0</li><li>15</li><li>0</li></ol><button class="showanswer" onclick="showhide(5)"><span id="btntext5">Show Answer</span></button> <button class="workspace" onclick="showworkspace(5)"><span id="btntext5">Workspace</span></button><div id="workspace5"></div><div class="testanswer" id="answer5"><p><strong>Answer:</strong> (d) 11.0</p><p><strong>Explanation:</strong> Precedence table in python</p><table class="alt"><tbody><tr><td>High</td><td>*, /, // and%</td></tr><tr><td>Low</td><td>+ and -</td></tr></tbody></table><p>If the operator precedence is same, the calculation starts from left to right.</p><p>Therefore, option (d) is the correct output of this program.</p></div><hr/><p class="pq">6) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">int1 = 0b0010 
print(int1)  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>0b0010</li><li>2</li><li>NameError: name '0b0010' is not defined</li><li>SyntaxError</li></ol><button class="showanswer" onclick="showhide(6)"><span id="btntext6">Show Answer</span></button> <button class="workspace" onclick="showworkspace(6)"><span id="btntext6">Workspace</span></button><div id="workspace6"></div><div class="testanswer" id="answer6"><p><strong>Answer:</strong> (b) 2</p><p><strong>Explanation:</strong> "0b0010" value is a binary value. Therefore, option (b) is the correct output of this program.</p></div><hr/><p class="pq">7) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">word = "javatpoint" 
print(*word)  
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>javatpoint</li><li>j a v a t p o i n t</li><li>*word</li><li>SyntaxError: invalid syntax</li></ol><button class="showanswer" onclick="showhide(7)"><span id="btntext7">Show Answer</span></button> <button class="workspace" onclick="showworkspace(7)"><span id="btntext7">Workspace</span></button><div id="workspace7"></div><div class="testanswer" id="answer7"><p><strong>Answer:</strong> (b) j a v a t p o i n t</p><p><strong>Explanation:</strong> When a user prints a string with "*", that string is printed with the space in each word. Therefore, option (b) is the correct output of this program.</p></div><hr/><p class="pq">8) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">i = 2, 10
j = 3, 5
add = i + j
print(add) 
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>(5, 10)</li><li>20</li><li>(2, 10, 3, 5)</li><li>SyntaxError: invalid syntax</li></ol><button class="showanswer" onclick="showhide(8)"><span id="btntext8">Show Answer</span></button> <button class="workspace" onclick="showworkspace(8)"><span id="btntext8">Workspace</span></button><div id="workspace8"></div><div class="testanswer" id="answer8"><p><strong>Answer:</strong> (c) (2, 10, 3, 5)</p><p><strong>Explanation:</strong> "i" and "j" are tuples values. The tuple values are added to the bracket. Therefore, option (c) is the correct output of this program.</p></div><hr/><p class="pq">9) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print(int(6 == 6.0) * 3 + 4 % 5)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>22</li><li>18</li><li>20</li><li>7</li></ol><button class="showanswer" onclick="showhide(9)"><span id="btntext9">Show Answer</span></button> <button class="workspace" onclick="showworkspace(9)"><span id="btntext9">Workspace</span></button><div id="workspace9"></div><div class="testanswer" id="answer9"><p><strong>Answer:</strong> (d) 7</p><p><strong>Explanation:</strong> In the python programming language, (int(6 == 6.0)) is a valid condition but in other languages is not a valid condition. Therefore, option (d) is the correct output of this program.</p></div><hr/><p class="pq">10) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">i = 2
j = 3, 5
add = i + j
print(add) 
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>5, 5</li><li>5</li><li>(2 , 3 , 5)</li><li>TypeError</li></ol><button class="showanswer" onclick="showhide(10)"><span id="btntext10">Show Answer</span></button> <button class="workspace" onclick="showworkspace(10)"><span id="btntext10">Workspace</span></button><div id="workspace10"></div><div class="testanswer" id="answer10"><p><strong>Answer:</strong> (d) TypeError</p><p><strong>Explanation:</strong> In this program, "i" is the integer value, and "j" is the tuple value. The integer and tuple values cannot be added in the python programming language. Therefore, this program will print the "Typeerror".</p></div><hr/><p class="pq">11) How many control statements python supports?</p><ol class="pointsa"><li>Four</li><li>Five</li><li>Three</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(11)"><span id="btntext11">Show Answer</span></button> <button class="workspace" onclick="showworkspace(11)"><span id="btntext11">Workspace</span></button><div id="workspace11"></div><div class="testanswer" id="answer11"><p><strong>Answer:</strong> (c) Three</p><p><strong>Explanation:</strong> In the Python Programming Language, there are three types of control statements.</p><ol class="points"><li>Break</li><li>Continue</li><li>Pass statements</li></ol></div><hr/><p class="pq">12) How many keywords present in the python programming language?</p><ol class="pointsa"><li>32</li><li>61</li><li>33</li><li>27</li></ol><button class="showanswer" onclick="showhide(12)"><span id="btntext12">Show Answer</span></button> <button class="workspace" onclick="showworkspace(12)"><span id="btntext12">Workspace</span></button><div id="workspace12"></div><div class="testanswer" id="answer12"><p><strong>Answer:</strong> (c) 33</p><p><strong>Explanation:</strong> There are 33 keywords in python. In the Python Programming Language, keywords are reserved words for the program that is used to define the syntax and structure. You cannot use a keyword as a function name, variable name, or any other identifier.</p></div><hr/><p class="pq">13) Which of the following arithmetic operators cannot be used with strings in python?</p><ol class="pointsa"><li>+</li><li>*</li><li>-</li><li>All of the mentioned</li></ol><button class="showanswer" onclick="showhide(13)"><span id="btntext13">Show Answer</span></button> <button class="workspace" onclick="showworkspace(13)"><span id="btntext13">Workspace</span></button><div id="workspace13"></div><div class="testanswer" id="answer13"><p><strong>Answer:</strong> (c) -</p><p><strong>Explanation:</strong> In python, only (+) and (*), two arithmetic operators are used with string. Therefore, option (c) is the correct answer.</p></div><hr/><p class="pq">14) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print("java", 'point', sep='2')
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>javapoint2</li><li>japoint</li><li>java2point</li><li>javapoin2</li></ol><button class="showanswer" onclick="showhide(14)"><span id="btntext14">Show Answer</span></button> <button class="workspace" onclick="showworkspace(14)"><span id="btntext14">Workspace</span></button><div id="workspace14"></div><div class="testanswer" id="answer14"><p><strong>Answer:</strong> (c) java2point</p><p><strong>Explanation:</strong> The "sep" means separator that is used to add a separator between the two strings. Therefore, option (c) is the correct output of this program.</p></div><hr/><p class="pq">15) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print('It\'s ok, don\'t worry')
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>It's ok, don't worry</li><li>It\'s ok, don\'t worry</li><li>SyntaxError: EOL while scanning string literal</li><li>SyntaxError: invalid syntax</li></ol><button class="showanswer" onclick="showhide(15)"><span id="btntext15">Show Answer</span></button> <button class="workspace" onclick="showworkspace(15)"><span id="btntext15">Workspace</span></button><div id="workspace15"></div><div class="testanswer" id="answer15"><p><strong>Answer:</strong> (a) It's ok, don't worry</p><p><strong>Explanation:</strong> In the Python programming language, the backslash "\" is an escape character. Therefore, option (a) is the correct output of this program.</p></div><hr/><p class="pq">16) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">_ = '1 2 3 4 5 6'
print(_)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>SyntaxError: EOL while scanning string literal</li><li>SyntaxError: invalid syntax</li><li>NameError: name '_' is not defined</li><li>1 2 3 4 5 6</li></ol><button class="showanswer" onclick="showhide(16)"><span id="btntext16">Show Answer</span></button> <button class="workspace" onclick="showworkspace(16)"><span id="btntext16">Workspace</span></button><div id="workspace16"></div><div class="testanswer" id="answer16"><p><strong>Answer:</strong> (d) 1 2 3 4 5 6</p><p><strong>Explanation:</strong> "_" is a valid variable name. Therefore, option (d) is the correct output of this program.</p></div><hr/><p class="pq">17) Which of the following keywords is not reversed keyword in python?</p><ol class="pointsa"><li>None</li><li>class</li><li>goto</li><li>and</li></ol><button class="showanswer" onclick="showhide(17)"><span id="btntext17">Show Answer</span></button> <button class="workspace" onclick="showworkspace(17)"><span id="btntext17">Workspace</span></button><div id="workspace17"></div><div class="testanswer" id="answer17"><p><strong>Answer:</strong> (c) goto</p><p><strong>Explanation:</strong> "and", "class", and "None" are reversed keywords in python. So, option (c) is the correct answer.</p></div><hr/><p class="pq">18) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">a = '1 2'
print(a * 2)
print(a * 0)
print(a * -2)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>1 2 1 2</li><li>2 4</li><li>0</li><li>-1 -2 -1 -2</li></ol><button class="showanswer" onclick="showhide(18)"><span id="btntext18">Show Answer</span></button> <button class="workspace" onclick="showworkspace(18)"><span id="btntext18">Workspace</span></button><div id="workspace18"></div><div class="testanswer" id="answer18"><p><strong>Answer:</strong> (a) 1 2 1 2</p><p><strong>Explanation:</strong></p><ul class="points"><li>"a * 2" means, string prints 2 times.</li><li>"a * 0" means, string is empty.</li><li>Any string cannot be negative. Therefore, the string will not print any word.</li></ul></div><hr/><p class="pq">19) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">print(max("zoo 145 com"))
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>145</li><li>122</li><li>a</li><li>z</li></ol><button class="showanswer" onclick="showhide(19)"><span id="btntext19">Show Answer</span></button> <button class="workspace" onclick="showworkspace(19)"><span id="btntext19">Workspace</span></button><div id="workspace19"></div><div class="testanswer" id="answer19"><p><strong>Answer:</strong> (d) z</p><p><strong>Explanation:</strong> The ASCII value of the a-z lies in the range 97 - 122. So, the maximum value of the string is 122 (z = 122).</p></div><hr/><p class="pq">20) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">a = "123789"
while x in a:
    print(x, end=" ")
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>i i i i i i …</li><li>123789</li><li>SyntaxError</li><li>NameError</li></ol><button class="showanswer" onclick="showhide(20)"><span id="btntext20">Show Answer</span></button> <button class="workspace" onclick="showworkspace(20)"><span id="btntext20">Workspace</span></button><div id="workspace20"></div><div class="testanswer" id="answer20"><p><strong>Answer:</strong> (d) NameError</p><p><strong>Explanation:</strong> This program will print the NameError because 'x' is not defined in this code.</p></div><hr/><p class="pq">21) PVM is often called _________.</p><ol class="pointsa"><li>Python interpreter</li><li>Python compiler</li><li>Python volatile machine</li><li>Portable virtual machine</li></ol><button class="showanswer" onclick="showhide(21)"><span id="btntext21">Show Answer</span></button> <button class="workspace" onclick="showworkspace(21)"><span id="btntext21">Workspace</span></button><div id="workspace21"></div><div class="testanswer" id="answer21"><p><strong>Answer:</strong> (a) Python interpreter</p><p><strong>Explanation:</strong> PVM is a software that converts bytecode to machine code for a given OS. PVM is also called Python Interpreter, and that is why Python is called Interpreted Language.</p></div><hr/><p class="pq">22) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">i = {4, 5, 6}
i.update({2, 3, 4})
print(i)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>2 3 4 4 5 6</li><li>2 3 4 5 6</li><li>4 5 6 2 3 4</li><li>Error, duplicate element presents in list</li></ol><button class="showanswer" onclick="showhide(22)"><span id="btntext22">Show Answer</span></button> <button class="workspace" onclick="showworkspace(22)"><span id="btntext22">Workspace</span></button><div id="workspace22"></div><div class="testanswer" id="answer22"><p><strong>Answer:</strong> (b) 2 3 4 5 6</p><p><strong>Explanation:</strong> This is a valid syntax of the update function. Therefore, the option (b) is the correct output of this program.</p></div><hr/><p class="pq">23) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">i=(12, 20, 1, 0, 25)
i.sort()
print(i)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>0 1 12 20 25</li><li>1 12 20 25</li><li>FunctionError</li><li>AttributeError</li></ol><button class="showanswer" onclick="showhide(23)"><span id="btntext23">Show Answer</span></button> <button class="workspace" onclick="showworkspace(23)"><span id="btntext23">Workspace</span></button><div id="workspace23"></div><div class="testanswer" id="answer23"><p><strong>Answer:</strong> (d) AttributeError</p><p><strong>Explanation:</strong> In this program, "i" is the tuple value. The tuple value cannot be sorted in python language. Therefore, this program will print the "AttributeError".</p></div><hr/><p class="pq">24) Which of the following keywords is used for function declaration in Python language?</p><ol class="pointsa"><li>def</li><li>function_name</li><li>define</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(24)"><span id="btntext24">Show Answer</span></button> <button class="workspace" onclick="showworkspace(24)"><span id="btntext24">Workspace</span></button><div id="workspace24"></div><div class="testanswer" id="answer24"><p><strong>Answer:</strong> (a) def</p><p><strong>Explanation:</strong> In the python language, the def keyword is used to define the function.</p><p><strong>Syntax of the function declaration</strong></p><pre>def function_name(parameters):  
      block of function  
return expression</pre></div><hr/><p class="pq">25) Which of the following objects are present in the function header in python?</p><ol class="pointsa"><li>Function name and Parameters</li><li>Only function name</li><li>Only parameters</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(25)"><span id="btntext25">Show Answer</span></button> <button class="workspace" onclick="showworkspace(25)"><span id="btntext25">Workspace</span></button><div id="workspace25"></div><div class="testanswer" id="answer25"><p><strong>Answer:</strong> (a) Function name and Parameters</p><p><strong>Explanation:</strong> Function name and Parameter are both present in the function header in python.</p><pre>def function_name(parameters):  
      block of function  
return expression</pre></div><hr/><p class="pq">26) When a user does not use the return statement inside a function in Python, what will return the function in that case.</p><ol class="pointsa"><li>0</li><li>1</li><li>None</li><li>No output</li></ol><button class="showanswer" onclick="showhide(26)"><span id="btntext26">Show Answer</span></button> <button class="workspace" onclick="showworkspace(26)"><span id="btntext26">Workspace</span></button><div id="workspace26"></div><div class="testanswer" id="answer26"><p><strong>Answer:</strong> (c) None</p><p><strong>Explanation:</strong> When a user does not use the return statement inside a function in Python, the function will return the "None".</p></div><hr/><p class="pq">27) Which one of the following is the right way to call a function?</p><ol class="pointsa"><li>call function_name()</li><li>function function_name()</li><li>function_name()</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(27)"><span id="btntext27">Show Answer</span></button> <button class="workspace" onclick="showworkspace(27)"><span id="btntext27">Workspace</span></button><div id="workspace27"></div><div class="testanswer" id="answer27"><p><strong>Answer:</strong> (c) function_name()</p><p><strong>Explanation:</strong> To call a function in python language, it uses the function name followed by the parentheses.</p></div><hr/><p class="pq">28) Suppose a user wants to print the second value of an array, which has 5 elements. What will be the syntax of the second value of the array?</p><ol class="pointsa"><li>array[2]</li><li>array[1]</li><li>array[-1]</li><li>array[-2]</li></ol><button class="showanswer" onclick="showhide(28)"><span id="btntext28">Show Answer</span></button> <button class="workspace" onclick="showworkspace(28)"><span id="btntext28">Workspace</span></button><div id="workspace28"></div><div class="testanswer" id="answer28"><p><strong>Answer:</strong> (b) array[1]</p><p><strong>Explanation:</strong> The index of the array starts with 0. Therefore, the option (b) is the correct answer.</p></div><hr/><p class="pq">29) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">str1="python language"
str1.find("p")
print(str1)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>Print the index value of the p.</li><li>p</li><li>python language</li><li>AttributeError</li></ol><button class="showanswer" onclick="showhide(29)"><span id="btntext29">Show Answer</span></button> <button class="workspace" onclick="showworkspace(29)"><span id="btntext29">Workspace</span></button><div id="workspace29"></div><div class="testanswer" id="answer29"><p><strong>Answer:</strong> (c) python language</p><p><strong>Explanation:</strong> In this program, it will print the value of the str1. Therefore, the option (c) is the correct output of this program.</p></div><hr/><p class="pq">30) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">flag = ""
a = 0
i = 1
while(a &lt; 3):
    j = 1
    if flag:
        i = j * i + 5
    else:
        i = j * i + 1
    a = a + 1
print(i)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>12</li><li>4</li><li>11</li><li>16</li></ol><button class="showanswer" onclick="showhide(30)"><span id="btntext30">Show Answer</span></button> <button class="workspace" onclick="showworkspace(30)"><span id="btntext30">Workspace</span></button><div id="workspace30"></div><div class="testanswer" id="answer30"><p><strong>Answer:</strong> (b) 4</p><p><strong>Explanation:</strong> The output of this program is 4.</p></div><hr/><p class="pq">31) Study the following expression:</p><div class="codeblock"><textarea class="java" name="code">str = [(1, 1), (2, 2), (3, 3)]
</textarea></div><p><strong>What type of data is in this expression?</strong></p><ol class="pointsa"><li>String type</li><li>Array lists</li><li>List of tuples</li><li>str lists</li></ol><button class="showanswer" onclick="showhide(31)"><span id="btntext31">Show Answer</span></button> <button class="workspace" onclick="showworkspace(31)"><span id="btntext31">Workspace</span></button><div id="workspace31"></div><div class="testanswer" id="answer31"><p><strong>Answer:</strong> (c) List of tuples</p><p><strong>Explanation:</strong> The variable str has a list of tuples attached to it. Hence it is a list of tuples. So, option (c) is the correct answer.</p></div><hr/><p class="pq">32) Which of the following statements is not valid regarding the variable in python?</p><ol class="pointsa"><li>The variable_name can begin with alphabets</li><li>The variable_name can begin with an underscore</li><li>The variable_name can begin with a number</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(32)"><span id="btntext32">Show Answer</span></button> <button class="workspace" onclick="showworkspace(32)"><span id="btntext32">Workspace</span></button><div id="workspace32"></div><div class="testanswer" id="answer32"><p><strong>Answer:</strong> (c) The variable_name can begin with a number</p><p><strong>Explanation:</strong> The variable_name can begin with alphabets or underscore but cannot begin with numbers. So, option (c) is the correct answer.</p></div><hr/><p class="pq">33) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">a = 2
while(a &gt; -100):
    a = a - 1
    print(a)
</textarea></div><p><strong>How many times will this program run the loop?</strong></p><ol class="pointsa"><li>Infinite</li><li>102</li><li>2</li><li>1</li></ol><button class="showanswer" onclick="showhide(33)"><span id="btntext33">Show Answer</span></button> <button class="workspace" onclick="showworkspace(33)"><span id="btntext33">Workspace</span></button><div id="workspace33"></div><div class="testanswer" id="answer33"><p><strong>Answer:</strong> (b) 102</p><p><strong>Explanation:</strong> This loop will run the 1 to -100 (1, 0, -1,?, -100). So, option (b) is the correct answer.</p></div><hr/><p class="pq">34) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">arr = [3 , 2 , 5 , 6 , 0 , 7, 9]
add1 = 0
add2 = 0
for elem in arr:
    if (elem % 1 == 0):
        add1 = add1 + elem
        continue
    if (elem % 3 == 0):
        add2 = add2 + elem
print(add1 , end=" ")
print(add2)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>32 0</li><li>0 32</li><li>18 0</li><li>0 18</li></ol><button class="showanswer" onclick="showhide(34)"><span id="btntext34">Show Answer</span></button> <button class="workspace" onclick="showworkspace(34)"><span id="btntext34">Workspace</span></button><div id="workspace34"></div><div class="testanswer" id="answer34"><p><strong>Answer:</strong> (a) 32 0</p><p><strong>Explanation:</strong> The output of this program is (32, 0).</p></div><hr/><p class="pq">35) Which of the following statements is valid for "if statement"?</p><ol class="pointsa"><li>if f &gt;= 12:</li><li>if (f &gt;= 122)</li><li>if (f =&gt; 1222)</li><li>if f &gt;= 12222</li></ol><button class="showanswer" onclick="showhide(35)"><span id="btntext35">Show Answer</span></button> <button class="workspace" onclick="showworkspace(35)"><span id="btntext35">Workspace</span></button><div id="workspace35"></div><div class="testanswer" id="answer35"><p><strong>Answer:</strong> (a) if f &gt;= 12:</p><p><strong>Explanation:</strong> The "if statement" always ends with a colon (:). So, option (a) is the correct statement.</p></div><hr/><p class="pq">36) Which of the following blocks allows you to test the code blocks for errors?</p><ol class="pointsa"><li>except block</li><li>try block</li><li>finally block</li><li>None of the these</li></ol><button class="showanswer" onclick="showhide(36)"><span id="btntext36">Show Answer</span></button> <button class="workspace" onclick="showworkspace(36)"><span id="btntext36">Workspace</span></button><div id="workspace36"></div><div class="testanswer" id="answer36"><p><strong>Answer:</strong> (b) try block</p><p><strong>Explanation:</strong> The try block allows you to test the code blocks for errors in the python language.</p></div><hr/><p class="pq">37) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">try:
  print(file_name)
except:
  print("error comes in the line")
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>file_name</li><li>error</li><li>error comes in the line</li><li>file_name error comes in the line</li></ol><button class="showanswer" onclick="showhide(37)"><span id="btntext37">Show Answer</span></button> <button class="workspace" onclick="showworkspace(37)"><span id="btntext37">Workspace</span></button><div id="workspace37"></div><div class="testanswer" id="answer37"><p><strong>Answer:</strong> (c) error comes in the line</p><p><strong>Explanation:</strong> The try block will generate an error because file_name is not defined in the program. Therefore, the output of this program will be "error comes in the line".</p></div><hr/><p class="pq">38) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">i = 10
j = 8
assert i &gt; j, 'j = i + j'
print(j)
</textarea></div><p><strong>What will be the output of this program?</strong></p><ol class="pointsa"><li>18</li><li>8</li><li>No output</li><li>TypeError</li></ol><button class="showanswer" onclick="showhide(38)"><span id="btntext38">Show Answer</span></button> <button class="workspace" onclick="showworkspace(38)"><span id="btntext38">Workspace</span></button><div id="workspace38"></div><div class="testanswer" id="answer38"><p><strong>Answer:</strong> (b) 8</p><p><strong>Explanation:</strong> In this program, the assert keyword has been used to mislead the user. Therefore, this program will print the value of "j".</p></div><hr/><p class="pq">39) Study the following program:</p><div class="codeblock"><textarea class="java" name="code">class Student:
	print("Students of Section A")
Student()
